extern "C" int sprintf(char *, const char *, ...);

#define assert(x) ((void)0)

enum { BEACH_MAVERICKS = 6, SURFER_LAST = 14 };

class stringx
{
    char *chars;
    void *my_buf;
public:
    stringx(const char *str, int len = -1);
};

class game
{
    char padding[0x224];
    int levelid;
    int beachid;
public:
    int get_beach_id() { return beachid; }
};

extern game *g_game_ptr;

class JudgingSystem
{
public:
    struct RUN
    {
        float regionScores[3];

        float GetAverageScore() const
        {
            if (g_game_ptr->get_beach_id() != BEACH_MAVERICKS)
                return (regionScores[0]+regionScores[1]+regionScores[2])/3.0f;
            else
                return (regionScores[0]+regionScores[1])/2.0f;
        }
    };

    struct RESULT
    {
        RUN runs[3];
        int rank;

        float GetRunTotal() const { return runs[0].GetAverageScore() + runs[1].GetAverageScore() + runs[2].GetAverageScore(); }
    };

private:
    float skills[SURFER_LAST];
    bool isCompetitor[SURFER_LAST];
    char alignment[2];
    float difficulties[3];
    RESULT results[SURFER_LAST];

public:
    RESULT *GetCompetitionResults() { return results; }
};

class beach
{
public:
    JudgingSystem judges;
};

extern beach *g_beach_ptr;

class IGOFrontEnd
{
public:
    stringx GetCompStrTotal(const int surferIdx) const;
};

